const VERSION='1.4.61';
const MIN_PLAYERS=2;
const AVATAR_DATA={"1":"data:image/webp;base64,","2":"data:image/webp;base64,","3":"data:image/webp;base64,","4":"data:image/webp;base64,","5":"data:image/webp;base64,","6":"data:image/webp;base64,","7":"data:image/webp;base64,","8":"data:image/webp;base64,","9":"data:image/webp;base64,","10":"data:image/webp;base64,","11":"data:image/webp;base64,","12":"data:image/webp;base64,","13":"data:image/webp;base64,","14":"data:image/webp;base64,","15":"data:image/webp;base64,","16":"data:image/webp;base64,","17":"data:image/webp;base64,","18":"data:image/webp;base64,","19":"data:image/webp;base64,","20":"data:image/webp;base64,"};const avatars=Object.keys(AVATAR_DATA);
function avatarSVG(id,cls='avatarIcon'){const n=String(id);return `<img class="${cls}" data-avatar="${n}" src="${AVATAR_DATA[n]||AVATAR_DATA['1']}" alt="" draggable="false">`;}
const savedAvatar=localStorage.getItem('collageAvatar');
const state={screen:'home',name:localStorage.getItem('collageName')||'',avatar:/^(?:[1-9]|1[0-9]|20)$/.test(savedAvatar||'')?savedAvatar:'1',ws:null,pid:null,code:'',game:null,error:'',settings:{capacity:2,imagesPerPlayer:2,round1Images:4,imageSeconds:120,hostApproval:false,creationSeconds:120,votingSeconds:45},lobby:'My Collage',prompt:'',promptSubmitted:false,sourceSelected:null,sourceWorking:{},pieces:[],selected:null,drag:null,timerHandle:null,cutCanvas:null,cutPoints:[],cutZoom:1,cutImg:null,lastPhase:null,_lastImageCount:-1,_lastReadyCount:-1,_lastSubmittedCount:-1,serverClockOffset:0,lastTimerEnd:null,_lastPromptCount:-1,syncTimer:null,_lastFinalIndex:-1,_lastFinalVote:null,reconnectTimer:null,pingTimer:null,pongTimer:null,intentionalClose:false};
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
function send(action){if(state.ws?.readyState!==1)return false;try{state.ws.send(JSON.stringify({type:'ACTION',playerId:state.pid,action}));return true}catch{return false;}}
function saveSession(){if(state.pid&&state.code)localStorage.setItem('collageSession',JSON.stringify({pid:state.pid,code:state.code,name:state.name,avatar:state.avatar}))}
function clearSession(){localStorage.removeItem('collageSession')}
function stopConnectionWatch(){clearInterval(state.pingTimer);clearTimeout(state.pongTimer);state.pingTimer=null;state.pongTimer=null}
function startConnectionWatch(){stopConnectionWatch();state.pingTimer=setInterval(()=>{if(state.ws?.readyState!==1)return;try{state.ws.send(JSON.stringify({type:'ACTION',playerId:state.pid,action:{type:'CLIENT_PING'}}));clearTimeout(state.pongTimer);state.pongTimer=setTimeout(()=>{try{state.ws.close()}catch{}},8000)}catch{}},5000)}
function scheduleReconnect(){if(state.intentionalClose||state.reconnectTimer||!state.pid||!state.code)return;state.reconnectTimer=setTimeout(()=>{state.reconnectTimer=null;connect(null,true)},1500)}

function connect(first,resume=false){clearTimeout(state.reconnectTimer);state.reconnectTimer=null;state.intentionalClose=false;if(state.ws&&(state.ws.readyState===0||state.ws.readyState===1)){try{state.ws.close()}catch{}}stopConnectionWatch();const proto=location.protocol==='https:'?'wss':'ws';state.ws=new WebSocket(proto+'://'+location.host+'/ws');state.ws.onopen=()=>{startConnectionWatch();if(resume)state.ws.send(JSON.stringify({type:'RESUME',playerId:state.pid,code:state.code}));else first?.(state.ws)};state.ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='CLIENT_PONG'){clearTimeout(state.pongTimer);state.pongTimer=null}else if(m.type==='JOINED'){state.pid=m.playerId;state.code=m.code;saveSession();state.screen='game';state.error='';render(true)}else if(m.type==='SUBMISSION_ACCEPTED'){if(state.game?.phase==='ROUND'&&m.round===state.game.round){state.game.submissionStatus={...(state.game.submissionStatus||{}),[state.pid]:true};render(true)}}else if(m.type==='STATE'){const promptEl=state.game?.phase==='PROMPT_SUBMISSION'&&!state.promptSubmitted?document.querySelector('#prompt'):null;const draftPrompt=promptEl?.value??null;const promptFocused=promptEl&&document.activeElement===promptEl;const promptSelectionStart=promptEl?.selectionStart??null;const promptSelectionEnd=promptEl?.selectionEnd??null;const old=state.game?.phase,oldRound=state.game?.round,oldTimerEnd=state.game?.timerEndsAt;const receivedAt=Date.now();if(m.state.serverNow&&m.state.timerEndsAt!==oldTimerEnd)state.serverClockOffset=m.state.serverNow-receivedAt;state.game=m.state;if(draftPrompt!==null)state.prompt=draftPrompt;if(state.game.phase==='PROMPT_SUBMISSION'){state.promptSubmitted=!!state.game.prompts?.some(p=>p.ownerId===state.pid);/* prompt count is handled by updateLive */}else if(state.game.phase!=='ROUND'){state.pieces=[];state.selected=null;state.drag=null}if(old!==state.game.phase||oldRound!==state.game.round){state.lastTimerEnd=state.game.timerEndsAt;if(oldRound!==state.game.round)state.pieces=[];render(true)}else {updateLive();if(promptFocused&&!state.promptSubmitted){const next=document.querySelector('#prompt');if(next){next.focus();try{next.setSelectionRange(promptSelectionStart,promptSelectionEnd)}catch{}}}}}else if(m.type==='ERROR'){if(m.message==='That game session is no longer available.'){clearSession();state.pid=null;state.code='';state.game=null;state.screen='home';}state.error=m.message;render(true)}};state.ws.onclose=()=>{stopConnectionWatch();if(!state.intentionalClose){state.error='Connection lost — reconnecting…';render(true);scheduleReconnect();}}}
function home(){return `<div class="shell"><div class="hero"><div class="brand">SHUFFLE • COLLAGE</div><h1>COLLAGE</h1><div class="tag">Cut it. Build it. Shuffle it. 😈</div><div class="buildBadge">BUILD V${VERSION}</div><div class="menu"><button onclick="go('host')">🎮 Host Game</button><button onclick="go('join')">🚪 Join Game</button></div></div><div class="profile"><h3>Who are you?</h3><div class="profileNameRow"><div class="profileAvatarPreview">${avatarSVG(state.avatar,'profileAvatar')}</div><input value="${esc(state.name)}" oninput="setName(this.value)" placeholder="Nickname"></div><div class="avatars">${avatars.map(a=>`<button class="${a===state.avatar?'selected':''}" data-avatar="${a}" aria-label="Character ${a}" onclick="setAvatar('${a}')">${avatarSVG(a)}</button>`).join('')}</div></div><p class="roundNote">Shuffle testing build • 2-player minimum for testing</p></div>`}
function host(){return `<div class="shell hostShell"><div class="hostHeader"><div class="brand">HOST GAME</div><div class="buildMini">V${VERSION}</div></div><div class="hostTitle"><div><h2>Set up your chaos 🎨</h2><p>Everything here is ready to go — pick the rules, name your lobby and launch.</p></div><div class="hostBadge">SHUFFLE MODE</div></div><section class="hostNameCard"><div class="cardIcon">🏷️</div><div class="cardBody"><label>Lobby name</label><input value="${esc(state.lobby)}" oninput="state.lobby=this.value" placeholder="My Collage"></div></section><div class="hostSettingsGrid"><section class="settingCard"><div class="cardIcon">👥</div><div class="cardBody"><b>Players</b><small>How many people can join?</small>${hostSelect('capacity',Array.from({length:15},(_,i)=>i+2).map(v=>[v,v]),' players')}</div></section><section class="settingCard"><div class="cardIcon">🖼️</div><div class="cardBody"><b>Images per player</b><small>How many images each player adds</small>${hostSelect('imagesPerPlayer',Array.from({length:20},(_,i)=>[i+1,i+1]))}</div></section><section class="settingCard"><div class="cardIcon">🎲</div><div class="cardBody"><b>Round 1 images</b><small>Images each player starts with</small>${hostSelect('round1Images',[["all","All"],...Array.from({length:20},(_,i)=>[i+1,i+1])])}</div></section><section class="settingCard"><div class="cardIcon">⏳</div><div class="cardBody"><b>Image selection time</b><small>Time to build your image pool</small>${hostSelect('imageSeconds',[[30,"30 sec"],[60,"1 min"],[90,"1:30"],[120,"2 min"],[180,"3 min"],[240,"4 min"],[300,"5 min"]])}</div></section><section class="settingCard"><div class="cardIcon">⏱️</div><div class="cardBody"><b>Creation time</b><small>Time for each collage round</small>${hostSelect('creationSeconds',[[30,"30 sec"],[60,"1 min"],[90,"1:30"],[120,"2 min"],[180,"3 min"],[240,"4 min"],[300,"5 min"],[420,"7 min"],[600,"10 min"]])}</div></section><section class="settingCard"><div class="cardIcon">🗳️</div><div class="cardBody"><b>Voting time</b><small>Time for each showcase vote</small>${hostSelect('votingSeconds',[[15,"15 sec"],[30,"30 sec"],[45,"45 sec"],[60,"1 min"],[90,"1:30"],[120,"2 min"],[180,"3 min"],[300,"5 min"]])}</div></section><section class="settingCard toggleCard ${state.settings.hostApproval?'on':''}"><div class="cardIcon">🕵️</div><div class="cardBody"><b>Host image approval</b><small>Check the pool before prompts begin</small><label class="switchLine"><input type="checkbox" ${state.settings.hostApproval?'checked':''} onchange="state.settings.hostApproval=this.checked;render(true)"><span class="switch"></span><span>${state.settings.hostApproval?'ON':'OFF'}</span></label></div></section></div><div class="hostFooter"><div class="hostTip">💡 <b>Shuffle tip:</b> nothing is revealed until the final showcase, so players can’t influence each other.</div><div class="hostActions"><button class="secondary" onclick="go('home')">← Back</button><button onclick="startHost()">Create Lobby 🚀</button></div></div>${state.error?`<p class="error hostError">${esc(state.error)}</p>`:''}</div>`}
function hostSelect(key,options,suffix=''){return `<select onchange="state.settings['${key}']=this.value==='all'?'all':+this.value">${options.map(([v,label])=>`<option value="${v}" ${String(state.settings[key])===String(v)?'selected':''}>${label}${suffix}</option>`).join('')}</select>`}
function setting(label,key,min,max,allOption){return `<div class="setting"><small>${label}</small>${allOption?`<select onchange="state.settings[key]=this.value==='all'?'all':+this.value"><option value="all" ${state.settings[key]==='all'?'selected':''}>All</option>${Array.from({length:max-min+1},(_,i)=>{const v=min+i;return `<option value="${v}" ${state.settings[key]===v?'selected':''}>${v}</option>`}).join('')}</select>`:`<input type="number" min="${min}" max="${max}" value="${state.settings[key]}" onchange="state.settings[key]=+this.value">`}</div>`}
function join(){return `<div class="shell joinScreen"><div class="brand">JOIN GAME</div><h2>Join a Collage lobby</h2><div class="joinCallout">👋 <b>Enter your nickname below.</b></div><form class="form joinForm" onsubmit="event.preventDefault();startJoin()"><label for="joinName"><b>👤 Your nickname</b></label><input id="joinName" autocomplete="nickname" value="${esc(state.name)}" oninput="setName(this.value)" placeholder="Type your nickname here" autofocus><label for="joinCode"><b>🔑 Lobby code</b></label><input id="joinCode" value="${esc(state.code)}" oninput="state.code=this.value.toUpperCase()" placeholder="4-letter lobby code" maxlength="4" autocomplete="off"><button type="submit">Join Lobby →</button></form>${state.error?`<p class="error">${esc(state.error)}</p>`:''}<button class="secondary" onclick="go('home')">Back</button><p class="roundNote">Build V${VERSION}</p></div>`}
function lobby(){const g=state.game,me=g.players.find(p=>p.id===state.pid),connected=g.players.filter(p=>p.connected).length,minPlayers=g.minPlayers||MIN_PLAYERS,canStart=connected>=minPlayers;return `<div class="shell"><div class="brand">LOBBY</div><h2>${esc(g.name)}</h2><div class="code">${state.code}</div><p style="text-align:center">Send this code to your friends. Everyone joins from their own PC.</p><div class="players">${g.players.map(p=>`<div class="player">${avatarSVG(p.avatar,'playerAvatar')}<b>${esc(p.name)}</b>${p.host?' 👑':''}<span class="status">${p.connected?(p.host?'Host':p.ready?'Ready':'Not ready'):'✕ Offline'}</span></div>`).join('')}</div><div class="row" style="margin-top:18px">${me.host?`<button ${canStart?'':'disabled'} onclick="send({type:'START'})">${canStart?'Start Game 🚀':`Waiting for ${minPlayers} players…`}</button>`:`<button onclick="send({type:'SET_READY',ready:${!me.ready}})">${me.ready?'✓ Ready — click to undo':'Ready up'}</button>`}<span class="notice">${connected}/${g.settings.capacity} players • minimum ${minPlayers}</span></div></div>`}
function imageSubmit(){const g=state.game,me=g.players.find(p=>p.id===state.pid),mine=g.sources.filter(s=>s.ownerId===state.pid),need=g.settings.imagesPerPlayer,ready=!!g.imageReady?.[state.pid],readyCount=Object.values(g.imageReady||{}).filter(Boolean).length,remaining=Math.max(0,Math.ceil((g.timerEndsAt-(Date.now()+state.serverClockOffset))/1000));return `<div class="shell imageShell"><div class="stageTop"><div><div class="brand">IMAGE POOL</div><h2>🖼️ Build your image pool</h2><p>Find, upload or paste your images. Add exactly <b>${need}</b>.</p></div><div class="timer bigTimer">⏱ <span id="timerValue">${remaining}</span>s</div></div><div class="imageMethods"><button onclick="openImageSearch()">🔎 Find an image</button><button onclick="document.getElementById('file').click()">📁 Upload</button><button onclick="pasteHint()">📋 Paste</button><button class="secondary" onclick="surpriseMe()">🔀 Surprise me</button><input id="file" class="fileInput" type="file" accept="image/*" multiple onchange="files(this.files)"></div><div class="poolHeader"><h3>Your images</h3><span>${mine.length} / ${need}</span></div><div class="poolGrid">${mine.map(s=>`<div class="poolCard"><img src="${s.data}"><button class="removeBtn" onclick="removeSource('${s.id}')">✕ Remove</button></div>`).join('')||'<div class="emptyPool">Your pool is empty — find something weird.</div>'}</div><div class="imageFooter"><div class="notice">${ready?'✓ Ready — waiting for everyone':`${mine.length}/${need} added`}</div><button ${(!ready&&mine.length!==need)?'disabled':''} onclick="${ready?'imageUnready()':'imageReady()'}">${ready?`✓ Ready! ${readyCount}/${g.players.length}`:`Ready! ${readyCount}/${g.players.length}`}</button></div>${state.error?`<p class="error">${esc(state.error)}</p>`:''}</div>`}
function openImageSearch(){const modal=document.createElement('div');modal.className='searchModal';modal.innerHTML=`<div class="searchBox"><div class="searchHead"><div><h2>🔎 Find an image</h2><p>Select images, then add them to your pool.</p></div><button class="secondary" onclick="this.closest('.searchModal').remove()">✕</button></div><form class="searchForm" onsubmit="event.preventDefault();searchImages(this.q.value)"><input name="q" autofocus oninput="queueImageSearch(this.value)" placeholder="What are you looking for?"><button>Search</button></form><div id="searchResults" class="searchResults"><div class="searchEmpty">Search for anything — or try <b>Surprise me</b>.</div></div><div class="searchFooter"><span id="searchSelected">0 selected</span><button id="addSearchBtn" disabled onclick="addSearchSelection()">Add images</button></div></div>`;document.body.appendChild(modal);state.searchSelected=[];state.searchResults=[]}
let searchDebounce=null;function queueImageSearch(q){clearTimeout(searchDebounce);const term=String(q||'').trim();if(!term)return;searchDebounce=setTimeout(()=>searchImages(term),350)}
async function searchImages(q){q=String(q||'').trim();if(!q)return;const box=document.querySelector('#searchResults');if(box)box.innerHTML='<div class="searchEmpty">Searching…</div>';try{const r=await fetch(`/api/image-search?q=${encodeURIComponent(q)}`);const data=await r.json();if(!r.ok)throw new Error(data.error||'Search failed');state.searchResults=data.results||[];state.searchSelected=[];renderSearchResults()}catch(e){if(box)box.innerHTML=`<div class="searchEmpty">Could not search right now.</div>`}}
function renderSearchResults(){const box=document.querySelector('#searchResults');if(!box)return;box.innerHTML=state.searchResults.map((x,i)=>`<button class="searchResult ${state.searchSelected.includes(i)?'selected':''}" onclick="toggleSearchImage(${i})"><img src="${x.thumb}"><span class="check">${state.searchSelected.includes(i)?'✓':''}</span></button>`).join('')||'<div class="searchEmpty">No images found.</div>';const count=state.searchSelected.length;const el=document.querySelector('#searchSelected');if(el)el.textContent=`${count} selected`;const btn=document.querySelector('#addSearchBtn');const remaining=(state.game?.settings.imagesPerPlayer||2)-(state.game?.sources?.filter(s=>s.ownerId===state.pid).length||0);if(btn){btn.disabled=count===0||count>remaining;btn.textContent=count?`Add ${count} image${count===1?'':'s'}`:'Add images'}}
function toggleSearchImage(i){const max=(state.game?.settings.imagesPerPlayer||2)-(state.game?.sources?.filter(s=>s.ownerId===state.pid).length||0);if(state.searchSelected.includes(i))state.searchSelected=state.searchSelected.filter(x=>x!==i);else if(state.searchSelected.length<max)state.searchSelected.push(i);renderSearchResults()}
async function addSearchSelection(){const selected=state.searchSelected.map(i=>state.searchResults[i]);const btn=document.querySelector('#addSearchBtn');if(!selected.length||!btn||btn.disabled)return;btn.disabled=true;btn.textContent='Adding…';const results=await Promise.all(selected.map(async x=>{for(const url of [x.url,x.thumb]){if(!url)continue;try{const r=await fetch('/api/image-fetch?url='+encodeURIComponent(url));const data=await r.json();if(r.ok&&data.data)return data.data}catch{}}return null}));const images=results.filter(Boolean);if(images.length)send({type:'ADD_SOURCES_BATCH',images});if(images.length<selected.length)state.error='Added '+images.length+' of '+selected.length+' selected images — one or more could not be loaded.';document.querySelector('.searchModal')?.remove();state.searchSelected=[]}
async function surpriseMe(){const terms=['funny animals','weird objects','space','cars','food','animals wearing clothes','random people','nature','retro','fantasy'];const q=terms[Math.floor(Math.random()*terms.length)];openImageSearch();setTimeout(()=>{const input=document.querySelector('.searchForm input');if(input)input.value=q;searchImages(q)},50)}
function approval(){const host=state.game.players.find(p=>p.id===state.pid)?.host;const empty=!state.game.sources.length;return `<div class="shell"><div class="brand">HOST CHECK</div><h2>🕵️ Approve the image pool</h2>${empty?'<div class="notice" style="margin-top:18px">No images in the pool — At least 1 image is required to start the game.</div>':`<div class="thumbs">${state.game.sources.map(s=>`<div class="thumb"><img src="${s.data}"><button onclick="send({type:'DELETE_SOURCE',sourceId:'${s.id}'})">Delete</button></div>`).join('')}</div>`}${host?(empty?'<button style="margin-top:18px" disabled>Need at least 1 image</button>':`<button style="margin-top:18px" onclick="send({type:'APPROVAL_DONE'})">Looks good — continue →</button>`):'<p class="notice">Waiting for the host…</p>'}</div>`}
function prompts(){const count=state.game.prompts.length,total=state.game.players.length;const submitted=state.promptSubmitted||state.game.prompts.some(p=>p.ownerId===state.pid);return `<div class="shell"><div class="brand">PROMPT ROUND</div><h2>✍️ Give everyone something ridiculous to make</h2>${submitted?`<div class="promptSubmitted">✓ Prompt submitted!</div><div class="row" style="margin-top:14px"><span class="notice">${count}/${total} submitted • Waiting for the others…</span></div>`:`<textarea id="prompt" class="promptInput" style="min-height:130px" placeholder="Write a sentence, scenario or idea…">${esc(state.prompt)}</textarea><div class="row" style="margin-top:14px"><button onclick="submitPrompt()">Submit Prompt →</button><span class="notice">${count}/${total} submitted</span></div>`}</div>`}
function round(){const g=state.game,prompt=g.prompts.find(p=>p.id===g.currentPromptId)?.text||'',remaining=Math.max(0,Math.ceil((g.timerEndsAt-(Date.now()+state.serverClockOffset))/1000)),submittedCount=Object.values(g.submissionStatus||{}).filter(Boolean).length,submitted=!!g.submissionStatus?.[state.pid],displaySubmittedCount=submittedCount;if(g.round>0&&!state.pieces.length&&Array.isArray(g.currentPieces)){state.pieces=g.currentPieces.map(p=>({...p}))}return `<div class="shell wide"><div class="promptBanner"><div><small>ROUND ${g.round+1} OF ${g.players.length}</small><h2>${esc(prompt)}</h2></div><div class="timer">⏱ <span id="timerValue">${remaining}</span>s</div></div><div class="editorGrid"><aside><div class="sourcePanel">${g.round===0?`<h3>🖼 Your ingredients</h3><p>Select an image, then press <b>Cut</b>. Draw any shape around the bit you want.</p><div class="sourceList">${g.sources.map(s=>`<button class="sourceBtn ${state.sourceSelected===s.id?'active':''}" onclick="selectSource('${s.id}')"><img src="${state.sourceWorking[s.id]||s.data}"></button>`).join('')}</div>${state.sourceSelected?`<img class="sourcePreview" src="${state.sourceWorking[state.sourceSelected]||g.sources.find(s=>s.id===state.sourceSelected)?.data}">`:''}`:`<h3>🔀 Shuffled pieces</h3><p>These pieces came from another player's collage. Rearrange them.</p>`}</div><div class="toolPanel" style="margin-top:12px"><div class="toolbar" style="${submitted?'pointer-events:none;opacity:.45':''}">${g.round===0?`<button class="cutBtn" onclick="openCutTool()">✂ Cut freehand</button>`:''}<button onclick="rotate(-15)">↺</button><button onclick="rotate(15)">↻</button><button onclick="flip('x')">↔</button><button onclick="flip('y')">↕</button><button onclick="resizePiece(-10)">− Size</button><button onclick="resizePiece(10)">+ Size</button><button onclick="layer(-1)">↓ Back</button><button onclick="layer(1)">↑ Front</button></div><button style="width:100%;background:var(--green)" ${submitted?"disabled":""} onclick="submitCollage()">${submitted?'✓ Submitted '+displaySubmittedCount+'/'+g.players.length:'Submit collage ✓'}</button></div></aside><div class="canvas" id="canvas">${submitted?'':state.pieces.map(p=>`<img class="piece ${state.selected===p.id?'selected':''}" draggable="false" src="${p.src}" style="left:${p.x}%;top:${p.y}%;width:${p.w||24}%;transform:translate(-50%,-50%) rotate(${p.rotation||0}deg) scaleX(${p.flipX?-1:1}) scaleY(${p.flipY?-1:1});z-index:${p.z||0}" onpointerdown="pieceDown(event,'${p.id}')">`).join('')}</div></div><p class="roundNote">${g.round===0?'Freehand cut any shape you like.':'No cutting this round — only rearrange what you inherited.'} • Pieces: ${state.pieces.length} • Creations stay hidden until the final showcase.</p></div>`}
function canvasHTML(pieces=[]){return `<div class="canvas voteCanvas">${pieces.map(p=>`<img class="piece" draggable="false" src="${p.src}" style="left:${p.x}%;top:${p.y}%;width:${p.w||24}%;transform:translate(-50%,-50%) rotate(${p.rotation||0}deg) scaleX(${p.flipX?-1:1}) scaleY(${p.flipY?-1:1});z-index:${p.z||0}">`).join('')}</div>`}
function finalShowcase(){const g=state.game,remaining=Math.max(0,Math.ceil((g.timerEndsAt-Date.now())/1000)),prompt=g.prompts.find(p=>p.id===g.currentPromptId)?.text||'';const current=g.finalResults?.[g.finalIndex||0];const collages=current?.collages||{};const voted=!!g.myFinalVote;return `<div class="shell wide"><div class="brand">FINAL SHOWCASE • ${((g.finalIndex||0)+1)} OF ${g.finalResults?.length||g.players.length}</div><div class="promptBanner"><div><small>FINAL PROMPT</small><h2>${esc(prompt)}</h2></div><div class="timer">⏱ <span id="timerValue">${remaining}</span>s</div></div><p>Every finished collage for this prompt is shown now. Vote for one — <b>you cannot vote for your own.</b></p><div class="voteGrid">${Object.values(collages).map(c=>`<div class="voteCard">${canvasHTML(c.pieces)}${c.playerId===state.pid?'<div class="notice" style="margin-top:8px">Your collage</div>':`<button style="width:100%;margin-top:8px" ${voted?'disabled':''} onclick="send({type:'FINAL_VOTE',targetId:'${c.playerId}'})">${voted?'✓ Vote submitted':'Vote for this'}</button>`}</div>`).join('')}</div></div>`}
function final(){const g=state.game,rows=[...g.players].sort((a,b)=>(g.scores[b.id]||0)-(g.scores[a.id]||0));return `<div class="shell wide"><div class="brand">FINAL RESULTS</div><h1>🏆</h1><h2>The Collage Hall of Shame</h2>${rows.map((p,i)=>{const best=(g.bestCollages?.[p.id]||[]);return `<div class="finalResult"><div class="result"><b>${avatarSVG(p.avatar,'resultAvatar')}${i+1}. ${esc(p.name)}</b><span>${g.scores[p.id]||0} pts</span></div>${best.length?`<div class="bestLabel">Most successful collage${best.length>1?'es':''}</div><div class="bestGrid">${best.map(c=>canvasHTML(c.pieces)).join('')}</div>`:''}</div>`}).join('')}<p class="roundNote">Thanks for playing Shuffle. V${VERSION}</p></div>`}
function render(force=false){if(!force&&state.game?.phase===state.lastPhase)return;clearInterval(state.timerHandle);let html=state.screen==='home'?home():state.screen==='host'?host():state.screen==='join'?join():state.game?.phase==='LOBBY'?lobby():state.game?.phase==='IMAGE_SUBMISSION'?imageSubmit():state.game?.phase==='HOST_APPROVAL'?approval():state.game?.phase==='PROMPT_SUBMISSION'?prompts():state.game?.phase==='ROUND'?round():state.game?.phase==='FINAL_SHOWCASE'?finalShowcase():state.game?.phase==='FINAL'?final():`<div class="shell">Connecting…</div>`;app.innerHTML=html;if(state.game&&state.screen==='game'){const me=state.game.players.find(p=>p.id===state.pid);if(me)app.insertAdjacentHTML('beforeend',`<div class="playerHud">${avatarSVG(me.avatar,'hudAvatar')}<span>${esc(me.name)}</span></div>`);app.insertAdjacentHTML('beforeend',`<button class="leaveGameBtn" onclick="leaveGame()">↩ Leave Game</button>`);}state.lastPhase=state.game?.phase||null;bindPhase();startTimerIfNeeded();}
function bindPhase(){document.onpaste=state.game?.phase==='IMAGE_SUBMISSION'?onPaste:null;const file=document.querySelector('#file');if(file)file.addEventListener('change',e=>files(e.target.files));}
function startTimerIfNeeded(){clearInterval(state.timerHandle);state.timerHandle=null;if(!state.game?.timerEndsAt)return;const phase=state.game.phase;if(!['IMAGE_SUBMISSION','ROUND','FINAL_SHOWCASE'].includes(phase))return;state.timerHandle=setInterval(()=>{const remaining=Math.max(0,Math.ceil((state.game.timerEndsAt-(Date.now()+state.serverClockOffset))/1000));const el=document.querySelector('#timerValue');if(el)el.textContent=remaining;},250);}
function updateLive(){if(state.game?.phase==='PROMPT_SUBMISSION'){const promptCount=state.game.prompts?.length||0;if(promptCount!==state._lastPromptCount){state._lastPromptCount=promptCount;render(true);return;}}if(state.game?.phase==='LOBBY'){const el=document.querySelector('.players');if(el){const g=state.game;el.innerHTML=g.players.map(p=>`<div class="player">${avatarSVG(p.avatar,'playerAvatar')}<b>${esc(p.name)}</b>${p.host?' 👑':''}<span class="status">${p.connected?(p.host?'Host':p.ready?'Ready':'Not ready'):'✕ Offline'}</span></div>`).join('')}const g=state.game,me=g.players.find(p=>p.id===state.pid),connected=g.players.filter(p=>p.connected).length,minPlayers=g.minPlayers||MIN_PLAYERS;const row=document.querySelector('.shell .row');if(row&&me){row.innerHTML=me.host?`<button ${connected>=minPlayers?'':'disabled'} onclick="send({type:'START'})">${connected>=minPlayers?'Start Game 🚀':`Waiting for ${minPlayers} players…`}</button><span class="notice">${connected}/${g.settings.capacity} players • minimum ${minPlayers}</span>`:`<button onclick="send({type:'SET_READY',ready:${!me.ready}})">${me.ready?'✓ Ready — click to undo':'Ready up'}</button><span class="notice">${connected}/${g.settings.capacity} players • minimum ${minPlayers}</span>`;}}if(state.game?.phase==='IMAGE_SUBMISSION'){const count=state.game.sources.filter(s=>s.ownerId===state.pid).length,readyCount=Object.values(state.game.imageReady||{}).filter(Boolean).length;if(count!==state._lastImageCount||readyCount!==state._lastReadyCount){state._lastImageCount=count;state._lastReadyCount=readyCount;render(true);return;}startTimerIfNeeded();}if(state.game?.phase==='ROUND'){const submittedCount=Object.values(state.game.submissionStatus||{}).filter(Boolean).length;if(submittedCount!==state._lastSubmittedCount){state._lastSubmittedCount=submittedCount;render(true);return;}startTimerIfNeeded();}if(state.game?.phase==='FINAL_SHOWCASE'){if(state.game.finalIndex!==state._lastFinalIndex||state.game.myFinalVote!==state._lastFinalVote){state._lastFinalIndex=state.game.finalIndex;state._lastFinalVote=state.game.myFinalVote||null;render(true);return;}startTimerIfNeeded();}}
function leaveGame(){if(confirm('Leave this game and return to the home screen?'))go('home')}
function go(s){state.intentionalClose=true;clearTimeout(state.reconnectTimer);state.reconnectTimer=null;if(state.ws){try{state.ws.close()}catch{}}stopConnectionWatch();clearSession();state.pid=null;state.code='';state.screen=s;state.error='';state.game=null;state.lastPhase=null;render(true)}
function setName(v){state.name=v;localStorage.setItem('collageName',v)}function setAvatar(v){if(!/^(?:[1-9]|1[0-9]|20)$/.test(String(v)))return;state.avatar=String(v);localStorage.setItem('collageAvatar',state.avatar);render(true)}
function startHost(){clearSession();state.pid=null;state.intentionalClose=false;if(!state.name.trim()){state.error='Choose a nickname first.';render(true);return}connect(ws=>ws.send(JSON.stringify({type:'HOST_CREATE',name:state.name,avatar:state.avatar,lobbyName:state.lobby,settings:state.settings}))) }
function startJoin(){clearSession();state.pid=null;state.intentionalClose=false;const n=document.querySelector('#joinName')?.value.trim()||state.name.trim(),c=document.querySelector('#joinCode')?.value.trim().toUpperCase()||state.code.trim().toUpperCase();state.name=n;state.code=c;localStorage.setItem('collageName',n);if(!n){state.error='Enter a nickname first.';render(true);return}if(c.length<4){state.error='Enter the 4-letter lobby code.';render(true);return}connect(ws=>ws.send(JSON.stringify({type:'JOIN',name:n,avatar:state.avatar,code:c}))) }
function files(list){const need=state.game?.settings.imagesPerPlayer||2,current=state.game?.sources?.filter(s=>s.ownerId===state.pid).length||0;const allowed=Math.max(0,need-current);[...list].filter(f=>f.type.startsWith('image/')).slice(0,allowed).forEach(file=>{const reader=new FileReader();reader.onload=()=>send({type:'ADD_SOURCE',data:reader.result});reader.readAsDataURL(file)});}
function removeSource(id){send({type:'DELETE_OWN_SOURCE',sourceId:id})}
function imageReady(){send({type:'IMAGE_READY'})}
function imageUnready(){send({type:'IMAGE_UNREADY'})}
function pasteHint(){alert('Copy an image, then press Ctrl+V anywhere on this screen.')}
function onPaste(e){if(state.game?.phase!=='IMAGE_SUBMISSION')return;const items=[...(e.clipboardData?.items||[])];items.filter(i=>i.type.startsWith('image/')).forEach(i=>{const f=i.getAsFile();if(f)files([f])});}
function handleDrop(e){e.preventDefault();e.currentTarget.classList.remove('drag');files(e.dataTransfer.files)}
function submitSources(){send({type:'SUBMIT_SOURCES'})}
function submitPrompt(){if(state.promptSubmitted||state.game?.phase!=='PROMPT_SUBMISSION')return;const el=document.querySelector('#prompt');const t=el?.value.trim();if(!t)return;state.prompt=t;state.promptSubmitted=true;render(true);send({type:'ADD_PROMPT',text:t})}
function selectSource(id){state.sourceSelected=id;render(true)}
function openCutTool(){if(!state.sourceSelected){alert('Pick an image first.');return}const src=state.sourceWorking[state.sourceSelected]||state.game.sources.find(s=>s.id===state.sourceSelected)?.data;if(!src)return;const modal=document.createElement('div');modal.className='cutModal';modal.innerHTML=`<div class="cutBox"><div class="cutHead"><div><h2>✂ Draw your cut</h2><div class="cutHint">Draw any closed shape around exactly what you want.</div></div><div class="zoomControls"><button onclick="cutZoomBy(-0.25)">−</button><span id="cutZoomLabel">100%</span><button onclick="cutZoomBy(0.25)">+</button><button class="secondary" onclick="cutZoomFit()">Fit</button></div></div><div class="cutViewport"><canvas class="cutCanvas"></canvas></div><div class="row" style="margin-top:12px"><button onclick="finishCut()">Cut this shape</button><button class="secondary" onclick="closeCut()">Cancel</button><span class="notice">Freehand • any shape • zoom for precision</span></div></div>`;document.body.appendChild(modal);state.cutCanvas=modal.querySelector('canvas');state.cutPoints=[];state.cutZoom=1;const img=new Image();img.onload=()=>{state.cutImg=img;prepareCutCanvas();setupLasso()};img.src=src}
function prepareCutCanvas(){const c=state.cutCanvas,wrap=c.parentElement,ctx=c.getContext('2d');const maxW=Math.max(300,wrap.clientWidth-16),maxH=Math.max(240,wrap.clientHeight-16);c.width=Math.floor(maxW);c.height=Math.floor(maxH);drawCutCanvas();}
function drawCutCanvas(){const c=state.cutCanvas,img=state.cutImg;if(!c||!img)return;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);const fit=Math.min((c.width-20)/img.width,(c.height-20)/img.height);const scale=fit*state.cutZoom;const w=img.width*scale,h=img.height*scale;const ox=(c.width-w)/2,oy=(c.height-h)/2;state.cutDraw={scale,ox,oy};ctx.drawImage(img,ox,oy,w,h);if(state.cutPoints.length>1){ctx.beginPath();state.cutPoints.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle='#ff4f87';ctx.lineWidth=3;ctx.stroke()}}
function cutZoomBy(delta){state.cutZoom=Math.max(0.75,Math.min(2.5,state.cutZoom+delta));document.querySelector('#cutZoomLabel').textContent=Math.round(state.cutZoom*100)+'%';drawCutCanvas()}
function cutZoomFit(){state.cutZoom=1;document.querySelector('#cutZoomLabel').textContent='100%';drawCutCanvas()}
function closeCut(){document.querySelector('.cutModal')?.remove();state.cutCanvas=null;state.cutPoints=[];state.cutImg=null;state.cutDraw=null}
function setupLasso(){const c=state.cutCanvas;let drawing=false;const clampPoint=e=>{const d=state.cutDraw||{};const x=Math.max(d.ox||0,Math.min((d.ox||0)+(state.cutImg?.width||0)*(d.scale||1),e.offsetX));const y=Math.max(d.oy||0,Math.min((d.oy||0)+(state.cutImg?.height||0)*(d.scale||1),e.offsetY));return [x,y]};c.onpointerdown=e=>{drawing=true;c.setPointerCapture?.(e.pointerId);state.cutPoints=[clampPoint(e)];drawCutCanvas()};c.onpointermove=e=>{if(!drawing)return;state.cutPoints.push(clampPoint(e));drawCutCanvas()};c.onpointerup=e=>{if(!drawing)return;drawing=false;c.releasePointerCapture?.(e.pointerId);if(state.cutPoints.length>2){const [x,y]=state.cutPoints[0];state.cutPoints.push([x,y]);drawCutCanvas()}};c.onpointercancel=e=>{if(!drawing)return;drawing=false;c.releasePointerCapture?.(e.pointerId)}}
function finishCut(){const c=state.cutCanvas,img=state.cutImg,d=state.cutDraw;if(!c||!img||!d||state.cutPoints.length<8){alert('Draw a larger closed shape first.');return}const pts=state.cutPoints.map(([x,y])=>[(x-d.ox)/d.scale,(y-d.oy)/d.scale]);const valid=pts.filter(([x,y])=>x>=0&&x<=img.width&&y>=0&&y<=img.height);if(valid.length<3){alert('Keep the cut inside the image.');return}const xs=valid.map(p=>p[0]),ys=valid.map(p=>p[1]),minX=Math.max(0,Math.floor(Math.min(...xs))),minY=Math.max(0,Math.floor(Math.min(...ys))),maxX=Math.min(img.width,Math.ceil(Math.max(...xs))),maxY=Math.min(img.height,Math.ceil(Math.max(...ys)));const out=document.createElement('canvas');out.width=Math.max(1,maxX-minX);out.height=Math.max(1,maxY-minY);const o=out.getContext('2d');o.beginPath();pts.forEach(([x,y],i)=>i?o.lineTo(x-minX,y-minY):o.moveTo(x-minX,y-minY));o.closePath();o.clip();o.drawImage(img,-minX,-minY);const pieceSrc=out.toDataURL('image/png');const working=document.createElement('canvas');working.width=img.width;working.height=img.height;const w=working.getContext('2d');w.drawImage(img,0,0);w.globalCompositeOperation='destination-out';w.beginPath();pts.forEach(([x,y],i)=>i?w.lineTo(x,y):w.moveTo(x,y));w.closePath();w.fill();state.sourceWorking[state.sourceSelected]=working.toDataURL('image/png');const p={id:uid(),src:pieceSrc,x:50,y:50,w:Math.max(10,Math.min(60,(maxX-minX)/img.width*75)),rotation:0,flipX:false,flipY:false,z:state.pieces.length};state.pieces.push(p);state.selected=p.id;closeCut();syncCollage();render(true)}
function pieceDown(e,id){e.preventDefault();e.stopPropagation();const p=state.pieces.find(x=>x.id===id);if(!p)return;state.selected=id;const el=e.currentTarget,canvas=el.parentElement,r=canvas.getBoundingClientRect();state.drag={id,ox:e.clientX,oy:e.clientY,startX:p.x,startY:p.y,w:r.width,h:r.height};el.setPointerCapture?.(e.pointerId);el.onpointermove=ev=>{if(!state.drag)return;const dx=(ev.clientX-state.drag.ox)/state.drag.w*100,dy=(ev.clientY-state.drag.oy)/state.drag.h*100;p.x=Math.max(0,Math.min(100,state.drag.startX+dx));p.y=Math.max(0,Math.min(100,state.drag.startY+dy));el.style.left=p.x+'%';el.style.top=p.y+'%'};el.onpointerup=()=>{state.drag=null;el.onpointermove=null;el.onpointerup=null;syncCollage();render(true)}}
function rotate(d){const p=state.pieces.find(x=>x.id===state.selected);if(p){p.rotation=(p.rotation||0)+d;syncCollage();render(true)}}function flip(axis){const p=state.pieces.find(x=>x.id===state.selected);if(p){const k=axis==='x'?'flipX':'flipY';p[k]=!p[k];syncCollage();render(true)}}function layer(d){const p=state.pieces.find(x=>x.id===state.selected);if(!p)return;const ordered=[...state.pieces].sort((a,b)=>(a.z||0)-(b.z||0));const idx=ordered.findIndex(x=>x.id===p.id);const target=Math.max(0,Math.min(ordered.length-1,idx+d));if(target===idx)return;const other=ordered[target];const z=p.z||0;p.z=other.z||0;other.z=z;syncCollage();render(true)}
function resizePiece(d){const p=state.pieces.find(x=>x.id===state.selected);if(p){p.w=Math.max(1,Math.min(100,(p.w||24)+d));syncCollage();render(true)}}function syncCollage(){if(state.game?.phase!=='ROUND'||state.game?.submissionStatus?.[state.pid])return;clearTimeout(state.syncTimer);const pieces=state.pieces.map(p=>({...p}));state.syncTimer=setTimeout(()=>{state.syncTimer=null;if(state.game?.phase==='ROUND'&&!state.game?.submissionStatus?.[state.pid])send({type:'SYNC_COLLAGE',pieces:state.pieces.map(p=>({...p}))})},200)}function submitCollage(){
  if(state.game?.phase!=='ROUND'||state.game?.submissionStatus?.[state.pid])return;
  clearTimeout(state.syncTimer);state.syncTimer=null;
  const pieces=state.pieces.map(p=>({...p}));
  if(!send({type:'SUBMIT_COLLAGE',pieces})){
    state.error='Could not submit — connection to the game server was lost.';
    render(true);
  }
}
window.go=go;window.leaveGame=leaveGame;window.setName=setName;window.queueImageSearch=queueImageSearch;window.setAvatar=setAvatar;window.startHost=startHost;window.startJoin=startJoin;window.files=files;window.handleDrop=handleDrop;window.submitSources=submitSources;window.removeSource=removeSource;window.imageReady=imageReady;window.imageUnready=imageUnready;window.pasteHint=pasteHint;window.openImageSearch=openImageSearch;window.searchImages=searchImages;window.toggleSearchImage=toggleSearchImage;window.addSearchSelection=addSearchSelection;window.surpriseMe=surpriseMe;window.submitPrompt=submitPrompt;window.selectSource=selectSource;window.openCutTool=openCutTool;window.closeCut=closeCut;window.finishCut=finishCut;window.pieceDown=pieceDown;window.rotate=rotate;window.flip=flip;window.layer=layer;window.resizePiece=resizePiece;window.cutZoomBy=cutZoomBy;window.cutZoomFit=cutZoomFit;window.submitCollage=submitCollage;
render(true);
const savedSession=(()=>{try{return JSON.parse(localStorage.getItem('collageSession')||'null')}catch{return null}})();
if(savedSession?.pid&&savedSession?.code){state.pid=savedSession.pid;state.code=savedSession.code;state.name=savedSession.name||state.name;state.avatar=/^(?:[1-9]|1[0-9]|20)$/.test(savedSession.avatar||'')?savedSession.avatar:state.avatar;state.screen='game';connect(null,true)}
